package dev.sablelife.client;
import dev.sablelife.SableLife;import dev.sablelife.module.ModuleNetworking;import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.*;import net.minecraft.core.component.DataComponents;import net.minecraft.world.item.component.CustomData;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.RegisterMenuScreensEvent;import net.neoforged.neoforge.network.PacketDistributor;import java.util.*;
/** Samples are never storage. Explicit Shift handling avoids vanilla chest right-click routing. */
@EventBusSubscriber(modid=SableLife.MOD_ID,bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public class LootEditorScreen extends AbstractContainerScreen<ChestMenu> {
 private final Inventory inventory;private int selected,column,samplePress=-1,inventoryPress=-1;private Button mode,clear;private final List<EditBox> inputs=new ArrayList<>();private final List<Button> apply=new ArrayList<>(),minus=new ArrayList<>(),plus=new ArrayList<>();private static final List<String> KEYS=List.of("quantity","rule","rolls");
 public LootEditorScreen(ChestMenu menu,Inventory inventory,Component title){super(menu,inventory,title);this.inventory=inventory;}
 @SubscribeEvent public static void register(RegisterMenuScreensEvent e){e.register(SableLife.LOOT_CHEST.get(),LootEditorScreen::new);}
 private Component tr(String k){return Component.translatable("loot_editor.sablelife."+k);}private net.minecraft.nbt.CompoundTag data(){return menu.getContainer().getItem(40).getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();}
 private Button button(Component c,int x,int y,int w,Runnable r){return addRenderableWidget(LifeUiStyle.button(c,leftPos+x,topPos+y,w,18,r));}
 protected void send(String key,double value){var d=data();if(d.getBoolean("Ready")&&d.hasUUID("Id"))PacketDistributor.sendToServer(new ModuleNetworking.Action(menu.containerId,d.getInt("Revision"),d.getUUID("Id"),"loot_edit",key,value,Integer.toString(selected)));}
 protected boolean templateShiftDown(){return hasShiftDown();}
 protected void inventorySampleClick(int slot){var d=data();if(d.getBoolean("Ready")&&d.hasUUID("Id"))PacketDistributor.sendToServer(new ModuleNetworking.Action(menu.containerId,d.getInt("Revision"),d.getUUID("Id"),"loot_edit","copy_inventory",0,Integer.toString(slot)));}
 private int maximum(int i){return i==0?Math.max(1,menu.getSlot(selected).getItem().getMaxStackSize()):i==1?Math.max(100,data().getInt("MaxRule")):27;}
 private int current(int i){return i==0?menu.getSlot(selected).getItem().getCount():i==1?data().getInt("Rule"+selected):data().getInt("Rolls");}
 private void adjust(int i,int direction){
  int step=i==1&&!data().getBoolean("Weighted")?5:1,base=current(i),min=i==2?1:0,max=maximum(i);var input=inputs.get(i);
  // Focused editors deliberately ignore snapshots, so update their text with the same request.
  if(input.isFocused())try{int typed=Integer.parseInt(input.getValue());if(typed>=min&&typed<=max)base=typed;}catch(NumberFormatException ignored){}
  int next=Math.clamp(base+direction*step,min,max);input.setValue(Integer.toString(next));send(KEYS.get(i),next);
 }
 private void apply(int i){try{int n=Integer.parseInt(inputs.get(i).getValue());if(n>=(i==2?1:0)&&n<=maximum(i)){send(KEYS.get(i),n);inputs.get(i).setFocused(false);}}catch(NumberFormatException e){inputs.get(i).setTextColor(0xFF7777);}}
 @Override protected void init(){imageWidth=Math.max(360,Math.min(480,width-14));imageHeight=Math.max(220,Math.min(320,height-14));column=190;super.init();inputs.clear();apply.clear();minus.clear();plus.clear();
  for(int i=0;i<menu.slots.size();i++){Slot s;if(i<54){final int n=i;s=new Slot(menu.getContainer(),i,i<27?12+i%9*18:-10000,i<27?40+i/9*18:-10000){@Override public boolean isActive(){return n<27;}@Override public boolean mayPlace(ItemStack item){return false;}@Override public boolean mayPickup(Player p){return false;}};}else{int n=i-54,index=n<27?n+9:n-27;s=new Slot(inventory,index,12+n%9*18,imageHeight-85+(n<27?n/9*18:58));}s.index=i;menu.slots.set(i,s);}
  button(tr("back"),imageWidth-67,8,55,()->send("back",0));mode=button(Component.empty(),column,50,imageWidth-column-12,()->send("weighted",data().getBoolean("Weighted")?0:1));mode.setTooltip(Tooltip.create(tr("mode_help")));
  int w=imageWidth-column-12;for(int i=0;i<3;i++){final int n=i;int y=92+i*38;var f=addRenderableWidget(new EditBox(font,leftPos+column,topPos+y,w-88,18,tr(KEYS.get(i))));f.setMaxLength(5);f.setFilter(t->t.matches("[0-9]{0,5}"));inputs.add(f);minus.add(button(Component.literal("−"),column+w-84,y,22,()->adjust(n,-1)));plus.add(button(Component.literal("+"),column+w-58,y,22,()->adjust(n,1)));apply.add(button(Component.literal("✓"),column+w-32,y,32,()->apply(n)));f.setTooltip(Tooltip.create(tr("edit_help")));}
  clear=button(tr("clear"),column,imageHeight-28,w,()->send("clear",0));sync();
 }
 private void sync(){var d=data();boolean editable=d.getBoolean("Ready")&&d.getBoolean("Editable"),has=menu.getSlot(selected).hasItem();mode.active=editable;clear.active=editable&&has;mode.setMessage(tr(d.getBoolean("Weighted")?"weighted":"chance"));for(int i=0;i<inputs.size();i++){boolean active=editable&&(i==2?d.getBoolean("Weighted"):has);inputs.get(i).active=apply.get(i).active=minus.get(i).active=plus.get(i).active=active;inputs.get(i).setEditable(active);inputs.get(i).setTooltip(Tooltip.create(Component.translatable("loot_editor.sablelife.bounds",i==2?1:0,maximum(i)).append("\n").append(tr("edit_help"))));if(!inputs.get(i).isFocused())inputs.get(i).setValue(Integer.toString(current(i)));minus.get(i).active&=current(i)>(i==2?1:0);plus.get(i).active&=current(i)<maximum(i);}}
 @Override protected void containerTick(){super.containerTick();sync();}
 @Override public boolean mouseClicked(double x,double y,int button){
  if((button==0||button==1)&&templateShiftDown()){
   if(inventoryPress==button)return true;
   for(int i=54;i<menu.slots.size();i++){var s=menu.getSlot(i);if(x>=leftPos+s.x&&x<leftPos+s.x+16&&y>=topPos+s.y&&y<topPos+s.y+16){inventoryPress=button;if(data().getBoolean("Editable")&&s.hasItem())inventorySampleClick(i);return true;}}
  }
  for(int i=0;i<27;i++){var s=menu.getSlot(i);if(x>=leftPos+s.x&&x<leftPos+s.x+16&&y>=topPos+s.y&&y<topPos+s.y+16&&(button==0||button==1)){samplePress=button;selected=i;inputs.forEach(f->f.setFocused(false));var d=data();if(d.getBoolean("Editable")){if(templateShiftDown()){if(s.hasItem())adjust(1,button==0?1:-1);}else if(button==1||!menu.getCarried().isEmpty())sampleClick(i,button);}sync();return true;}}return super.mouseClicked(x,y,button);
 }
 protected void sampleClick(int slot,int button){minecraft.gameMode.handleInventoryMouseClick(menu.containerId,slot,button,ClickType.PICKUP,minecraft.player);}
 @Override public boolean mouseReleased(double x,double y,int button){if(inventoryPress==button){inventoryPress=-1;return true;}if(samplePress==button){samplePress=-1;return true;}return super.mouseReleased(x,y,button);}
 @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){if(inventoryPress==button)return true;return super.mouseDragged(x,y,button,dx,dy);}
 @Override public boolean keyPressed(int key,int scan,int modifiers){for(int i=0;i<inputs.size();i++)if(inputs.get(i).isFocused()&&key!=256){if(key==257||key==335){apply(i);return true;}return inputs.get(i).keyPressed(key,scan,modifiers);}return super.keyPressed(key,scan,modifiers);}
 @Override public boolean mouseScrolled(double x,double y,double h,double v){for(int i=0;i<inputs.size();i++)if(v!=0&&inputs.get(i).active&&inputs.get(i).isMouseOver(x,y)){adjust(i,(int)Math.signum(v));return true;}return super.mouseScrolled(x,y,h,v);}
 private void frame(GuiGraphics g,int x,int y,int color){g.fill(leftPos+x-1,topPos+y-1,leftPos+x+17,topPos+y+17,color);g.fill(leftPos+x,topPos+y,leftPos+x+16,topPos+y+16,0xFF4B4557);}
 @Override protected void renderBg(GuiGraphics g,float p,int x,int y){g.fill(leftPos-2,topPos-2,leftPos+imageWidth+2,topPos+imageHeight+2,0xFF19151D);g.fill(leftPos,topPos,leftPos+imageWidth,topPos+imageHeight,0xFF9B614E);g.fill(leftPos+3,topPos+3,leftPos+imageWidth-3,topPos+imageHeight-3,0xFF242632);g.fill(leftPos+column-8,topPos+32,leftPos+column-6,topPos+imageHeight-8,0xFF9770B5);for(int i=0;i<27;i++){var s=menu.getSlot(i);frame(g,s.x,s.y,i==selected?0xFFD9C4ED:0xFF82728F);}for(int i=54;i<menu.slots.size();i++){var s=menu.getSlot(i);frame(g,s.x,s.y,0xFF82728F);}}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,font.plainSubstrByWidth(title.getString(),imageWidth-80),10,12,0xE6D8EA,false);g.drawString(font,tr("templates"),12,27,0xD9C4ED,false);g.drawString(font,tr("copy_note"),12,104,0xBDA5D0,false);g.drawString(font,playerInventoryTitle,12,imageHeight-98,0xD9C4ED,false);var item=menu.getSlot(selected).getItem();var name=Component.translatable("loot_editor.sablelife.slot",selected+1).append(" · ").append(item.isEmpty()?tr("empty"):item.getHoverName());g.drawString(font,font.plainSubstrByWidth(name.getString(),imageWidth-column-12),column,34,0xD9C4ED,false);for(int i=0;i<inputs.size();i++)g.drawString(font,tr(i==1?(data().getBoolean("Weighted")?"weight":"probability"):KEYS.get(i)),column,inputs.get(i).getY()-topPos-11,0xD9C4ED,false);}
 @Override public void render(GuiGraphics g,int x,int y,float p){sync();renderBackground(g,x,y,p);super.render(g,x,y,p);renderTooltip(g,x,y);if(hoveredSlot!=null&&hoveredSlot.index<27&&!hoveredSlot.hasItem())g.renderTooltip(font,tr("template_help"),x,y);}
}
